select id, effective_from, currency, tier_prices, discounts, element_at(tier_prices, 1) as entry_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, array_min(tier_prices) as lowest_price, slice(tier_limits, 1, 2) as first_two_limits, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices from price_tiers where currency in ('USD', 'THB')
